mapper.update:
UPDATE fb_wiki_writeback
SET status = 'RUNNING', update_time = #{now}
WHERE id = #{id}

UPDATE fb_wiki_writeback
SET remote_task_id = #{remoteTaskId}, update_time = #{now}
WHERE id = #{id}

UPDATE fb_wiki_writeback
SET status = 'SUCCESS', last_error = NULL, update_time = #{now}
WHERE id = #{id}

UPDATE fb_wiki_writeback
SET status = 'FAILED', last_error = #{lastError},
    next_retry_time = #{nextRetryTime}, update_time = #{now}
WHERE id = #{id}

UPDATE fb_wiki_writeback
SET status = 'PENDING', retry_count = #{retryCount},
    next_retry_time = #{nextRetryTime}, update_time = #{now}
WHERE id = #{id}
